<?php blog_head('Article revision history', 'Private saved revisions for this article.', true); ?>
<main class="blog-shell blog-admin-shell" id="blog-main"><?php blog_admin_navigation('posts'); ?><header class="blog-admin-header"><div><p class="blog-eyebrow">Saved editorial history</p><h1>Article revisions</h1></div><a href="<?= esc(blog_url('admin/posts/edit/' . $postId)) ?>">← Back to the editor</a></header><p class="blog-history-intro"><strong><?= esc($record['title']) ?></strong><br>The latest <?= BLOG_REVISION_LIMIT ?> saved versions are kept. Restoring creates a new private draft; it never publishes an older version automatically.</p>
<?php if ($errors): ?><div class="blog-notice blog-notice--error" role="alert"><?php foreach ($errors as $error): ?><p><?= esc($error) ?></p><?php endforeach; ?></div><?php endif; ?>
<?php if (!$revisions): ?><p class="blog-notice">No saved revisions yet. The next article save will preserve its current version and add the new one.</p><?php else: ?><div class="blog-history-layout"><nav class="blog-history-list" aria-label="Saved article versions"><?php foreach ($revisions as $revision): $item = json_decode($revision['snapshot_json'], true, 32, JSON_THROW_ON_ERROR); ?><a href="<?= esc(blog_url('admin/revisions/' . $postId, ['revision' => $revision['id']])) ?>"<?= $selected && $selected['id'] === $revision['id'] ? ' aria-current="page"' : '' ?>><strong><?= esc($item['title']) ?></strong><span><?= esc(gmdate('j M Y, H:i', strtotime($revision['created_at'] . ' UTC'))) ?> UTC · <?= esc($revision['editor'] ?: 'Administrator') ?></span><small><?= ($item['status'] ?? '') === 'published' ? 'Published version' : 'Draft version' ?><?= $revision['source_revision_id'] ? ' · restored copy' : '' ?></small></a><?php endforeach; ?></nav><section class="blog-history-detail" aria-label="Revision details"><?php if (!$selected): ?><p>Select a saved version to review its content and image metadata before restoring.</p><?php else: ?><p class="blog-eyebrow">Saved <?= esc(gmdate('j M Y, H:i', strtotime($selected['created_at'] . ' UTC'))) ?> UTC</p><h2><?= esc($snapshot['title']) ?></h2><?php if (!empty($snapshot['excerpt'])): ?><p><?= esc($snapshot['excerpt']) ?></p><?php endif; ?><?php $revisionImage = blog_article_image($snapshot['image'] ?? null); if ($revisionImage): ?><figure class="blog-history-image"><img src="<?= esc($revisionImage['url']) ?>" alt="<?= esc($snapshot['image_alt'] ?? '') ?>"><figcaption><?= esc($snapshot['image_caption'] ?? '') ?><?php if (!empty($snapshot['image_credit'])): ?><span><?= esc($snapshot['image_credit']) ?></span><?php endif; ?></figcaption></figure><?php endif; ?><details class="blog-history-content"><summary>Review the saved article body</summary><div class="blog-prose"><?= blog_clean_html($snapshot['content'] ?? '') ?></div></details><div class="blog-notice">Restoring saves this content as a <strong>draft</strong> and removes the article from public publication until you review and publish it again. Its current URL is preserved. Missing images or categories may need to be replaced.</div><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="restore"><input type="hidden" name="revision_id" value="<?= (int) $selected['id'] ?>"><input type="hidden" name="edit_version" value="<?= (int) $record['edit_version'] ?>"><button class="button" type="submit">Restore as a private draft</button></form><?php endif; ?></section></div><?php endif; ?></main><?php blog_foot(); ?>
